//! Runtime support for code generated by `ron2-derive`. Not public API.
//!
//! Keeping this logic here instead of in the expansion keeps the generated
//! code small and free of name-resolution hazards in the user's crate.

use alloc::{borrow::Cow, format, string::ToString, vec::Vec};

use crate::{
    ast::{Expr, SeqItem, StructBody, StructExpr, TupleElement},
    convert::{AstMapAccess, FromRon, expr_type_name},
    error::{Error, ErrorKind, Result},
    schema::{Field, TypeKind},
};

fn type_mismatch(
    expected: impl Into<alloc::string::String>,
    found: &str,
    span: crate::Span,
) -> Error {
    Error::with_span(
        ErrorKind::TypeMismatch {
            expected: expected.into(),
            found: found.to_string(),
        },
        span,
    )
}

/// Check that a named struct or variant expression carries the expected name.
pub fn check_struct_name(s: &StructExpr<'_>, expected: &str) -> Result<()> {
    let found = s.name.name.as_ref();
    if found == expected {
        Ok(())
    } else {
        Err(type_mismatch(
            format!("struct {expected}"),
            &format!("struct {found}"),
            s.name.span,
        ))
    }
}

/// Open a struct with named fields: `(a: 1)` or `Name(a: 1)`.
///
/// With `accepts_empty` (every field has a default), `()` and `Name()` are
/// accepted as well and yield an access without fields. `fields` lists the
/// expected field names for the error message on `()`.
pub fn struct_access<'a>(
    expr: &'a Expr<'a>,
    name: &'static str,
    fields: &'static [&'static str],
    accepts_empty: bool,
) -> Result<AstMapAccess<'a>> {
    match expr {
        Expr::AnonStruct(s) => AstMapAccess::from_anon(s, Some(name)),
        Expr::Struct(s) => {
            check_struct_name(s, name)?;
            match &s.body {
                Some(StructBody::Fields(body)) => {
                    AstMapAccess::from_fields(body, Some(name), s.span)
                }
                Some(StructBody::Tuple(t)) if accepts_empty && t.elements.is_empty() => {
                    Ok(AstMapAccess::empty(Some(name), s.span))
                }
                _ => Err(type_mismatch(
                    format!("struct {name}"),
                    "non-struct body",
                    s.span,
                )),
            }
        }
        Expr::Unit(u) if accepts_empty => Ok(AstMapAccess::empty(Some(name), u.span)),
        _ => {
            let found = expr_type_name(expr);
            let expected = if found == "unit" && !fields.is_empty() {
                format!("struct {name} with fields: {}", fields.join(", "))
            } else {
                format!("struct {name}")
            };
            Err(type_mismatch(expected, found, *expr.span()))
        }
    }
}

/// Open the body of a struct-like enum variant: `Variant(a: 1)`, and
/// `Variant()` or bare `Variant` (like a unit variant) when every field has a
/// default.
pub fn variant_access<'a>(
    s: &'a StructExpr<'a>,
    name: &'static str,
    accepts_empty: bool,
) -> Result<AstMapAccess<'a>> {
    match &s.body {
        Some(StructBody::Fields(body)) => AstMapAccess::from_fields(body, Some(name), s.span),
        Some(StructBody::Tuple(t)) if accepts_empty && t.elements.is_empty() => {
            Ok(AstMapAccess::empty(Some(name), s.span))
        }
        None if accepts_empty => Ok(AstMapAccess::empty(Some(name), s.span)),
        _ => Err(type_mismatch(
            format!("struct variant {name}"),
            "non-struct variant body",
            s.span,
        )),
    }
}

/// The elements of a tuple struct, which may be written as `Name(..)`,
/// `(..)` or `[..]`.
pub enum TupleElements<'a> {
    /// `Name(..)` or `(..)`.
    Tuple(&'a [TupleElement<'a>]),
    /// `[..]`.
    Seq(&'a [SeqItem<'a>]),
}

impl<'a> TupleElements<'a> {
    /// The element at `index`, which the length check has proven to exist.
    #[must_use]
    pub fn get(&self, index: usize) -> &'a Expr<'a> {
        match self {
            Self::Tuple(elements) => &elements[index].expr,
            Self::Seq(items) => &items[index].expr,
        }
    }

    fn len(&self) -> usize {
        match self {
            Self::Tuple(elements) => elements.len(),
            Self::Seq(items) => items.len(),
        }
    }
}

/// Open a tuple struct with exactly `len` elements.
pub fn tuple_struct_elements<'a>(
    expr: &'a Expr<'a>,
    name: &'static str,
    len: usize,
) -> Result<TupleElements<'a>> {
    let elements = match expr {
        Expr::Tuple(t) => TupleElements::Tuple(&t.elements),
        Expr::Seq(s) => TupleElements::Seq(&s.items),
        Expr::Struct(s) => {
            check_struct_name(s, name)?;
            match &s.body {
                Some(StructBody::Tuple(t)) => TupleElements::Tuple(&t.elements),
                _ => {
                    return Err(type_mismatch(
                        format!("tuple struct {name}"),
                        "non-tuple body",
                        s.span,
                    ));
                }
            }
        }
        _ => {
            return Err(type_mismatch(
                format!("tuple struct {name}"),
                expr_type_name(expr),
                *expr.span(),
            ));
        }
    };
    if elements.len() != len {
        return Err(type_mismatch(
            format!("tuple with {len} elements"),
            &format!("tuple with {} elements", elements.len()),
            *expr.span(),
        ));
    }
    Ok(elements)
}

/// Open the body of a tuple enum variant with exactly `len` elements.
pub fn tuple_variant_elements<'a>(
    s: &'a StructExpr<'a>,
    name: &'static str,
    len: usize,
) -> Result<&'a [TupleElement<'a>]> {
    let Some(StructBody::Tuple(t)) = &s.body else {
        return Err(type_mismatch(
            format!("tuple variant {name}"),
            "non-tuple variant body",
            s.span,
        ));
    };
    if t.elements.len() != len {
        return Err(type_mismatch(
            format!("tuple variant {name} with {len} elements"),
            &format!("tuple with {} elements", t.elements.len()),
            s.span,
        ));
    }
    Ok(&t.elements)
}

/// Accept a unit struct written as `()` or `Name`.
pub fn unit_struct(expr: &Expr<'_>, name: &'static str) -> Result<()> {
    match expr {
        Expr::Unit(_) => Ok(()),
        Expr::Struct(s) if s.body.is_none() => check_struct_name(s, name),
        _ => Err(type_mismatch(
            format!("unit struct {name}"),
            expr_type_name(expr),
            *expr.span(),
        )),
    }
}

/// Accept a unit variant written as `Variant` or `Variant()`.
pub fn unit_variant(s: &StructExpr<'_>, name: &'static str) -> Result<()> {
    match &s.body {
        None => Ok(()),
        Some(StructBody::Tuple(t)) if t.elements.is_empty() => Ok(()),
        _ => Err(type_mismatch(
            format!("unit variant {name}"),
            "variant with content",
            s.span,
        )),
    }
}

/// Error for an enum value written as `Some(..)` or `None` when the enum has
/// no variant of that name.
#[must_use]
pub fn unexpected_option(enum_name: &'static str, expr: &Expr<'_>) -> Error {
    let found = match expr {
        Expr::Option(opt) if opt.value.is_some() => "option Some",
        Expr::Option(_) => "option None",
        _ => expr_type_name(expr),
    };
    type_mismatch(format!("enum {enum_name}"), found, *expr.span())
}

/// Error for a value that is not an enum variant at all.
#[must_use]
pub fn expected_enum(enum_name: &'static str, expr: &Expr<'_>) -> Error {
    type_mismatch(
        format!("enum {enum_name}"),
        expr_type_name(expr),
        *expr.span(),
    )
}

/// Error for an unknown variant name.
#[must_use]
pub fn unknown_variant(
    s: &StructExpr<'_>,
    enum_name: &'static str,
    expected: &'static [&'static str],
) -> Error {
    Error::with_span(
        ErrorKind::UnknownVariant {
            variant: Cow::Owned(s.name.name.to_string()),
            expected,
            outer: Some(Cow::Borrowed(enum_name)),
        },
        s.name.span,
    )
}

/// Error for serializing an enum variant marked `#[ron(skip)]`.
#[must_use]
pub fn skipped_variant(enum_name: &'static str, variant: &'static str) -> Error {
    Error::new(ErrorKind::Message(format!(
        "enum variant {enum_name}::{variant} is marked #[ron(skip)] and cannot be serialized"
    )))
}

/// Reject fields of `access` that were not consumed.
///
/// `names` lists every accepted field, including those of flattened fields;
/// it only runs when there is an unknown field.
pub fn deny_unknown_fields(
    access: &AstMapAccess<'_>,
    names: impl FnOnce(&mut Vec<&'static str>),
) -> Result<()> {
    access.deny_unknown_fields_with(|| {
        let mut list = Vec::new();
        names(&mut list);
        Cow::Owned(list)
    })
}

/// Schema of a `#[ron(flatten)]` field.
///
/// It is optional when the flattened value may contribute no fields: it has a
/// default, is an `Option`, or is a map collecting the remaining fields.
#[must_use]
pub fn flattened_field(name: &str, kind: TypeKind, has_default: bool) -> Field {
    let optional = has_default || matches!(kind, TypeKind::Option(_) | TypeKind::Map { .. });
    let field = if optional {
        Field::optional(name, kind)
    } else {
        Field::new(name, kind)
    };
    field.with_flatten()
}

/// Field types allowed with `#[ron(explicit)]`: options read only from
/// `Some(..)` or `None`.
#[diagnostic::on_unimplemented(
    message = "`#[ron(explicit)]` requires an `Option<T>` field, but this field is `{Self}`",
    label = "not an `Option`"
)]
pub trait ExplicitOption: Sized {
    /// Read the value, rejecting a bare (implicit `Some`) value.
    fn from_explicit(expr: &Expr<'_>) -> Result<Self>;
}

impl<T: FromRon> ExplicitOption for Option<T> {
    fn from_explicit(expr: &Expr<'_>) -> Result<Self> {
        match expr {
            Expr::Option(opt) => match &opt.value {
                None => Ok(None),
                Some(inner) => Ok(Some(T::from_ast(&inner.expr)?)),
            },
            other => Err(type_mismatch(
                "Some(...) or None",
                expr_type_name(other),
                *other.span(),
            )),
        }
    }
}

struct Explicit<T>(T);

impl<T: ExplicitOption> FromRon for Explicit<T> {
    fn from_ast(expr: &Expr<'_>) -> Result<Self> {
        T::from_explicit(expr).map(Self)
    }
}

/// Read a required `#[ron(explicit)]` field.
pub fn read_explicit<T: ExplicitOption>(
    access: &mut AstMapAccess<'_>,
    name: &'static str,
) -> Result<T> {
    access.required::<Explicit<T>>(name).map(|e| e.0)
}

/// Read an `#[ron(explicit)]` field that has a default.
pub fn read_explicit_or<T: ExplicitOption>(
    access: &mut AstMapAccess<'_>,
    name: &'static str,
    default: impl FnOnce() -> T,
) -> Result<T> {
    Ok(access
        .optional::<Explicit<T>>(name)?
        .map_or_else(default, |e| e.0))
}
